        for new_row, new_col in neighbors:
            if is_valid(new_row, new_col):
                if dfs(new_row, new_col):
                    return True

        path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    if dfs(start[0], start[1]):
        return path
    else:
        return []
