    cols = len(grid[0])
    visited = set()
    path = []

    def get_neighbors(row, col):
        neighbors = []
        if row > 0 and grid[row - 1][col] != '#':
            neighbors.append((row - 1, col))
        if row < rows - 1 and grid[row + 1][col] != '#':
            neighbors.append((row + 1, col))
        if col > 0 and grid[row][col - 1] != '#':
            neighbors.append((row, col - 1))
        if col < cols - 1 and grid[row][col + 1] != '#':
            neighbors.append((row, col + 1))
        return neighbors

    def dfs(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True

        visited.add((row, col))
        path.append((row, col))

        for neighbor_row, neighbor_col in get_neighbors(row, col):
            if (neighbor_row, neighbor_col) not in visited:
                if dfs(neighbor_row, neighbor_col):
                    return True

        path.pop()
        return False

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal and grid[start[0]][start[1]] != '#':
        return [start]

    if dfs(start[0], start[1]):
        return path
    else:
        return []
