    visited = {start}
    parent = {}

    while queue:
        row, col = queue.popleft()

        if (row, col) == goal:
            path = []
            curr = goal
            while curr != start:
                path.append(curr)
                curr = parent[curr]
            path.append(start)
            return path[::-1]

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

